const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const VALUES = [3, 8, 12, 17, 24, 31, 40];
const DIMMED_OPACITY = 0.55;
const stack = document.createElement("div");
stack.className = "mo-stack mo-d-stack";
const track = document.createElement("div");
track.className = "mo-d-track";
const cellsHost = document.createElement("div");
cellsHost.className = "mo-d-cells";
const pointer = document.createElement("div");
pointer.className = "mo-d-pointer";
const arrow = document.createElement("div");
arrow.className = "mo-d-arrow";
const pointerLabel = document.createElement("span");
pointerLabel.textContent = "mid";
pointer.append(arrow, pointerLabel);
track.append(cellsHost, pointer);
const noteArea = document.createElement("div");
noteArea.className = "mo-d-notes";
const makeNote = (text) => {
  const note = document.createElement("p");
  note.className = "mo-d-note";
  note.textContent = text;
  noteArea.append(note);
  return note;
};
const small = makeNote("17 is too small");
const big = makeNote("31 is too big");
const found = makeNote("Found 24 at index 4");
stack.append(track, noteArea);
ctx.root.append(stack);
const cells = VALUES.map((value, index) => {
  const cell = document.createElement("div");
  cell.className = "mo-d-cell";
  const box = document.createElement("div");
  box.className = "mo-d-box";
  box.textContent = String(value);
  const label = document.createElement("span");
  label.className = "mo-d-index";
  label.textContent = String(index);
  cell.append(box, label);
  cellsHost.append(cell);
  return cell;
});
const boxes = cells.map((cell) => cell.firstElementChild);
const pointerX = (index) =>
  cells[index].getBoundingClientRect().left + cells[index].getBoundingClientRect().width / 2 -
  track.getBoundingClientRect().left - pointer.offsetWidth / 2;
const ring = document.createElement("div");
ring.className = "mo-d-ring";
boxes[4].append(ring);
gsap.set([small, big, found, ring], { opacity: 0 });
gsap.set(pointer, { x: pointerX(3), opacity: 0 });
ctx.timeline.from(cells, { opacity: 0, y: 40, duration: 0.4, stagger: 0.08, ease: "power3.out" }, 0);
ctx.timeline.to(pointer, { opacity: 1, duration: 0.4 }, cue(0.1));
ctx.timeline.to(small, { opacity: 1, duration: 0.4 }, cue(0.2));
ctx.timeline.to(boxes.slice(0, 4), { opacity: DIMMED_OPACITY, duration: 0.4 }, cue(0.3));
ctx.timeline.to(small, { opacity: 0, duration: 0.3 }, cue(0.4));
ctx.timeline.to(pointer, { x: pointerX(5), duration: 0.5, ease: "power2.inOut" }, cue(0.4));
ctx.timeline.to(big, { opacity: 1, duration: 0.4 }, cue(0.5));
ctx.timeline.to(boxes.slice(5), { opacity: DIMMED_OPACITY, duration: 0.4 }, cue(0.6));
ctx.timeline.to(big, { opacity: 0, duration: 0.3 }, cue(0.7));
ctx.timeline.to(pointer, { x: pointerX(4), duration: 0.5, ease: "power2.inOut" }, cue(0.7));
ctx.timeline.to(found, { opacity: 1, duration: 0.4 }, cue(0.85));
ctx.timeline.to(ring, { opacity: 1, duration: 0.4 }, cue(0.85));

