.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-d-stack {
  width: 100%;
  align-items: center;
}
.mo-s-{{sceneId}} .mo-d-track {
  position: relative;
  width: 100%;
  padding-bottom: calc(var(--mo-unit) * 9);
}
.mo-s-{{sceneId}} .mo-d-cells {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: calc(var(--mo-unit) * 1.2);
}
.mo-s-{{sceneId}} .mo-d-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--mo-unit) * 0.8);
}
.mo-s-{{sceneId}} .mo-d-box {
  position: relative;
  display: flex;
  width: 100%;
  aspect-ratio: 1;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--mo-border);
  border-radius: calc(var(--mo-unit) * 1.4);
  background: var(--mo-surface);
  font-family: var(--mo-font-mono);
  font-size: var(--mo-text-subtitle);
  font-weight: 700;
}
.mo-s-{{sceneId}} .mo-d-index {
  font-family: var(--mo-font-mono);
  font-size: var(--mo-text-small);
  color: var(--mo-text-secondary);
}
.mo-s-{{sceneId}} .mo-d-pointer {
  position: absolute;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--mo-unit) * 0.4);
  font-size: var(--mo-text-small);
  font-weight: 700;
}
.mo-s-{{sceneId}} .mo-d-arrow {
  width: 0;
  height: 0;
  border-left: calc(var(--mo-unit) * 1.2) solid transparent;
  border-right: calc(var(--mo-unit) * 1.2) solid transparent;
  border-bottom: calc(var(--mo-unit) * 1.8) solid var(--mo-accent);
}
.mo-s-{{sceneId}} .mo-d-ring {
  position: absolute;
  inset: calc(var(--mo-unit) * -0.6);
  border: 4px solid var(--mo-accent);
  border-radius: calc(var(--mo-unit) * 1.8);
  pointer-events: none;
}
.mo-s-{{sceneId}} .mo-d-notes {
  position: relative;
  width: 100%;
  min-height: calc(var(--mo-text-subtitle) * 1.6);
}
.mo-s-{{sceneId}} .mo-d-note {
  position: absolute;
  inset: 0;
  margin: 0;
  text-align: center;
  font-size: var(--mo-text-subtitle);
  font-weight: 600;
  line-height: 1.25;
}
